import { useState, useRef } from 'react';
import axios from 'axios';

const docs = [
  { name: 'sample.pdf',       meta: '31 pages · 292 chunks · 2h ago', status: 'Indexed',    color: 'var(--green)', icon: '📕', prog: 100 },
  { name: 'project_spec.docx',meta: '8 pages · 64 chunks · 1d ago',   status: 'Indexed',    color: 'var(--green)', icon: '📘', prog: 100 },
  { name: 'diagram.png',      meta: 'OCR processing · 12 chunks',      status: 'Processing', color: 'var(--warn)',  icon: '🖼', prog: 75 },
  { name: 'report_q1.pdf',    meta: 'Failed · permission error',        status: 'Failed',     color: 'var(--red)',   icon: '📕', prog: 100 },
];

export default function Upload({ API }) {
  const [uploadStatus, setUploadStatus] = useState('');
  const [dragging, setDragging] = useState(false);
  const inputRef = useRef();

  const uploadFile = async (file) => {
    if (!file) return;
    setUploadStatus(`⏳ Uploading ${file.name}...`);
    const fd = new FormData();
    fd.append('file', file);
    try {
      const { data } = await axios.post(`${API}/upload-pdf`, fd);
      setUploadStatus(`✅ ${data.message}`);
    } catch {
      setUploadStatus('❌ Upload failed. Check backend connection.');
    }
  };

  return (
    <div>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 20 }}>
        <div>
          <div style={{ fontSize: '1rem', fontWeight: 700 }}>Document Upload</div>
          <div style={{ fontSize: '0.65rem', color: 'var(--text3)', fontFamily: 'var(--mono)', marginTop: 2 }}>OCR → Embeddings → Vector Index</div>
        </div>
      </div>

      {/* Drop Zone */}
      <div
        onClick={() => inputRef.current.click()}
        onDragOver={e => { e.preventDefault(); setDragging(true); }}
        onDragLeave={() => setDragging(false)}
        onDrop={e => { e.preventDefault(); setDragging(false); uploadFile(e.dataTransfer.files[0]); }}
        style={{
          border: `2px dashed ${dragging ? 'var(--accent)' : 'var(--border2)'}`,
          borderRadius: 14, padding: 40, textAlign: 'center', cursor: 'pointer',
          background: dragging ? 'rgba(59,130,246,0.06)' : 'rgba(59,130,246,0.02)',
          marginBottom: 20, transition: 'all 0.3s'
        }}>
        <input ref={inputRef} type="file" accept=".pdf,.docx,.png,.jpg" style={{ display: 'none' }} onChange={e => uploadFile(e.target.files[0])} />
        <div style={{ fontSize: '2.5rem', marginBottom: 10 }}>📂</div>
        <div style={{ fontSize: '1rem', fontWeight: 600, marginBottom: 6 }}>Drop files here or click to browse</div>
        <div style={{ fontSize: '0.72rem', color: 'var(--text3)', marginBottom: 14 }}>PDF, DOCX, PNG, JPG — OCR processed automatically</div>
        <div style={{ display: 'flex', gap: 8, justifyContent: 'center', flexWrap: 'wrap' }}>
          {['📄 PDF', '📝 DOCX', '🖼 PNG/JPG'].map(t => (
            <span key={t} style={{ padding: '3px 10px', borderRadius: 20, fontSize: '0.62rem', fontFamily: 'var(--mono)', border: '1px solid var(--border2)', color: 'var(--text3)' }}>{t}</span>
          ))}
        </div>
        {uploadStatus && <div style={{ marginTop: 12, fontSize: '0.72rem', color: 'var(--green)' }}>{uploadStatus}</div>}
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 14 }}>
        {/* Doc List */}
        <div style={{ background: 'var(--surface)', border: '1px solid var(--border)', borderRadius: 12, overflow: 'hidden' }}>
          <div style={{ padding: '12px 16px', borderBottom: '1px solid var(--border)', fontSize: '0.75rem', fontWeight: 600, display: 'flex', justifyContent: 'space-between' }}>
            <span>Indexed Documents</span>
            <span style={{ color: 'var(--text3)', fontFamily: 'var(--mono)', fontSize: '0.62rem' }}>{docs.length} files</span>
          </div>
          {docs.map(({ name, meta, status, color, icon, prog }) => (
            <div key={name} style={{ display: 'flex', alignItems: 'center', gap: 12, padding: '12px 16px', borderBottom: '1px solid rgba(30,45,69,0.6)' }}>
              <div style={{ width: 36, height: 36, borderRadius: 8, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '1.1rem', background: `${color}18`, flexShrink: 0 }}>{icon}</div>
              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={{ fontSize: '0.78rem', fontWeight: 500, color: 'var(--text)', marginBottom: 2, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{name}</div>
                <div style={{ fontSize: '0.62rem', color: 'var(--text3)', fontFamily: 'var(--mono)', marginBottom: 4 }}>{meta}</div>
                <div style={{ height: 3, background: 'var(--border)', borderRadius: 2, overflow: 'hidden' }}>
                  <div style={{ height: '100%', width: `${prog}%`, background: status === 'Failed' ? 'var(--red)' : status === 'Processing' ? 'var(--warn)' : 'linear-gradient(90deg, var(--accent), var(--cyan))', borderRadius: 2 }} />
                </div>
              </div>
              <span style={{ padding: '2px 8px', borderRadius: 20, fontSize: '0.6rem', fontFamily: 'var(--mono)', background: `${color}18`, color, border: `1px solid ${color}40`, flexShrink: 0 }}>{status}</span>
            </div>
          ))}
        </div>

        {/* KB Stats */}
        <div style={{ background: 'var(--surface)', border: '1px solid var(--border)', borderRadius: 12, padding: 16 }}>
          <div style={{ fontSize: '0.78rem', fontWeight: 600, marginBottom: 12 }}>🧠 Knowledge Base Stats</div>
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 10, marginBottom: 14 }}>
            {[['368', 'Total Chunks'], ['3', 'Active Docs'], ['384', 'Vector Dims'], ['FAISS', 'Index Type']].map(([val, lbl]) => (
              <div key={lbl} style={{ background: 'var(--bg2)', border: '1px solid var(--border)', borderRadius: 8, padding: 12 }}>
                <div style={{ fontSize: '1.2rem', fontWeight: 700, fontFamily: 'var(--mono)', color: 'var(--accent)' }}>{val}</div>
                <div style={{ fontSize: '0.6rem', color: 'var(--text3)', marginTop: 2 }}>{lbl}</div>
              </div>
            ))}
          </div>
          <div style={{ fontSize: '0.7rem', color: 'var(--text3)', fontFamily: 'var(--mono)' }}>Last updated: 2 hours ago</div>
          <button style={{ marginTop: 10, width: '100%', padding: '8px', borderRadius: 7, border: '1px solid var(--border)', background: 'var(--surface2)', color: 'var(--text2)', fontSize: '0.72rem', cursor: 'pointer', fontFamily: 'var(--sans)' }}>
            🔄 Rebuild Index
          </button>
        </div>
      </div>
    </div>
  );
}
